            // Update B if present
            if (m > 0) {
                for (int l = 0; l < m; ++l) {
                    B(l1, l) -= t * B(icolum, l);
                }
            }
        }
    }

    // Interchange columns - corrected version
    // Create inverse permutation vector
    VectorXi invp = VectorXi::Zero(n);
    for (int i = 0; i < n; ++i) {
        // index(i,1) is the column that was placed at position i
        // so invp[index(i,1)] = i
        int col_idx = index(i, 1);
        if (col_idx >= 0 && col_idx < n) {
            invp(col_idx) = i;
        }
    }

    // Apply inverse permutation to columns of A
    MatrixXd A_temp = A;
    for (int j = 0; j < n; ++j) {
        A.col(j) = A_temp.col(invp(j));
    }

    // Check if matrix is singular
    ising = 1;
    for (int k = 0; k < n; ++k) {
        if (index(k, 2) != 1) {
            ising = 2;
            break;
        }
    }
}

